def decode(encode: str) -> str:
    s = encode[::-1]
    out = []
    i = 0
    while i < len(s):
        # 合法编码只有 32、65..90、97..122：以 '1' 开头的一定是三位数 100..122，其余都是两位数
        width = 3 if s[i] == '1' else 2
        out.append(chr(int(s[i:i + width])))
        i += width
    return "".join(out)
